  lemma IntervalSampleIsMeasurePreserving(a: int, b: int)
    requires a < b
    ensures Measures.IsMeasurePreserving(Rand.eventSpace, Rand.prob, Rand.eventSpace, Rand.prob, s => Model.IntervalSample(a, b)(s).rest)
