    requires n > 0
  {
    var empiricalMean := empiricalSum / n as real;
    var diff := RealArith.Abs(empiricalMean - trueMean);
    var threshold := 4.0 * 4.0 * trueVariance / n as real;
    if diff * diff > threshold {
