   Lemmas
  *******/

  // Correctness theorem for Model.Sample
  // Equation (4.12) / PROB_BERN_UNIFORM
  lemma UniformFullCorrectness(n: nat, i: nat)
    requires 0 <= i < n
    ensures
      var e := iset s | Model.Sample(n)(s).Equals(i);
      e in Rand.eventSpace &&
      Rand.prob(e) == 1.0 / (n as real)
  {}

