    requires n > 0
    ensures 0 <= Model.Sample(n)(s).value < n
  {}

  lemma IntervalSampleBound(a: int, b: int, s: Rand.Bitstream)
    requires a < b
    ensures a <= Model.IntervalSample(a, b)(s).value < b
  {
    SampleBound(b-a, s);
  }

