    var np1 := (n + 1) as real;
    assert mp1 > 0.0;
    assert np1 > 0.0;
    calc {
      mp1 <= np1;
    ==
      mp1 / np1 <= 1.0;
    ==
      (1.0 / np1) * mp1 <= (1.0 / mp1) * mp1;
    == { RealArith.MultiplicationCancelMonotonic(mp1, 1.0 / np1, 1.0 / mp1); }
      1.0 / np1 <= 1.0 / mp1;
    ==
      OneOverNPlus1(m) >= OneOverNPlus1(n);
