  {
    var aSeeds := Monad.BitstreamsWithValueIn(h, aSet);
    var restBSeeds := Monad.BitstreamsWithRestIn(h, bSeeds);
    assert Rand.prob(aSeeds * restBSeeds) == Rand.prob(aSeeds) * Rand.prob(restBSeeds) by {
