            self.unambiguous(),
            self.safe_inv(),
            self.sound_inv(),
            self.strict_inv(),
            self.nonmal_inv(),
            self.serialize_inv(),
            self.serialize_dps_inv(),
            self.equiv_general_inv(),
    ;
}

