    open spec fn productive_inv(&self) -> bool {
        true
    }

    broadcast proof fn lemma_productive(&self, s: Seq<u8>)
        requires
            self.safe_inv(),
            self.productive_inv(),
        ensures
            #[trigger] self.spec_parse(s) matches Some((n, _)) ==> n > 0,
    ;
}

