    proof fn lemma_serialize_equiv(&self, v: Self::SVal, obuf: Seq<u8>)
        requires
            self.equiv_general_inv(),
        ensures
            self.spec_serialize_dps(v, obuf) == self.spec_serialize(v) + obuf,
    ;
