        assert(self.strict_inv());
        self.0.lemma_parse_strict_consumption(ibuf);
        if let Some((n1, v1)) = self.0.spec_parse(ibuf) {
            self.1.lemma_parse_strict_consumption(ibuf[n1..]);
        }
    }
}

