            self.safe_inv(),
            self.no_lookahead_inv(),
        ensures
            self.spec_parse(i1) matches Some((n, v)) ==>
            0 <= n <= i2.len() ==> i2[0..n] == i1[0..n] ==>
            self.spec_parse(i2) == Some((n, v)),
