pub trait StrictCombinator:
    SafeParser +
    Productive +
    StrictParser +
    NonMalleable +
    GoodSerializer +
    NonTailFmt +
    SPRoundTripDps +
    EquivSerializersGeneral {

}

impl<Body> StrictCombinator for Body where
    Body:
        SafeParser +
        Productive +
        StrictParser +
        NonMalleable +
        GoodSerializer +
        NonTailFmt +
        SPRoundTripDps +
        EquivSerializersGeneral,
