  lemma PermutationsPreserveCardinality<T>(p: seq<T>, s: seq<T>)
    requires R: multiset(p) == multiset(s)
    ensures |p| == |s|
  {
    calc {
      |p|;
      { MultisetAndSequenceCardinality(p); }
      |multiset(p)|;
      { assert multiset(p) == multiset(s) by { reveal R; }}
      |multiset(s)|;
      { MultisetAndSequenceCardinality(s); }
      |s|;
    }
  }


}
