    requires n > 0
    requires num <= den
    modifies r
  {
    var t := 0;
    for i := 0 to n {
      var b := r.BernoulliSample(num, den);
      if b {
        t := t + 1;
      }
    }
    TestBernoulliIsWithin3SigmaOfTrueMean(n, t as real, (num as real) / (den as real), "p(true)");
  }

